import heapq


def _ledger(data, sequence_first, discounted, refunds):
    cutoff = data.get("cutoff", 10**9)
    rounding = data["rounding"]
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        revision = event.get("revision", 0)
        key = ((sequence, revision, position) if sequence_first
               else (revision, position))
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    def rounded(numerator):
        if rounding == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = net if discounted else raw
        tax = rounded(base * event.get("tax_bp", 0))
        value = net + tax
        if refunds and event.get("kind") == "refund":
            value = -value
        key = str(event.get("account", "default")) + "|" + str(event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + value
    return {"balances": balances}


def _build_ledger(sequence_first, discounted, refunds):
    return lambda data: _ledger(data, sequence_first, discounted, refunds)


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})
    choices = [[None] + [row["version"] for row in packages[name]] for name in names]
    best = None
    best_result = None

    for vector in product(*choices):
        selected = {name: version for name, version in zip(names, vector)
                    if version is not None}
        if any(version in blocked.get(name, []) for name, version in selected.items()):
            continue
        if any(name in selected and selected[name] != version
               for name, version in pins.items()):
            continue
        if any(name not in selected or not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue

        rows = {}
        for name, version in selected.items():
            rows[name] = next(row for row in packages[name] if row["version"] == version)
        edges = {}
        valid = True
        for name, row in rows.items():
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in selected or not dep["min"] <= selected[target] <= dep["max"]:
                    valid = False
                    break
                deps.append(target)
            edges[name] = deps
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in selected:
                valid = False
                break
            reachable.add(name)
            stack.extend(edges[name])
        if not valid or reachable != set(selected):
            continue

        state = {}
        def acyclic(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not acyclic(child) for child in edges[name]):
                return False
            state[name] = 2
            return True
        if not all(acyclic(name) for name in selected):
            continue

        key = tuple(-1 if value is None else value for value in vector)
        if best is None or key < best:
            best = key
            best_result = selected

    if best_result is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_result}


def _component_07(data):
    jobs = [job for job in data["jobs"] if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit_for.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, 0)
    distances = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, 0)]
    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full and used == data["coupons"]:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            next_node = edge["v"]
            next_mask = mask | bit_for.get(next_node, 0)
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, next_used)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_used))
    return {"arrival": None}


